import {pendingLeaf,requestedLeaf} from './temple-journey.js';
import {ensureCharacter} from './character-profile.js';
import {requireMember} from './member-gate.js?v=3.21';
import {appearance,cleanNote} from './garden-state.js';
import {createSanctuaryPresence} from './garden-presence.js';
const $=id=>document.getElementById(id),world=$('garden-world'),avatar=$('garden-avatar');
const stations={altar:{x:50,y:57,title:'ตั้งจิตหน้าพระพิฆเนศ',note:'พักใจสักครู่ แล้วมอบคำอวยพรดี ๆ ให้ตัวเอง',label:'A MOMENT OF STILLNESS'},ball:{x:28,y:74,title:'ซุ้มลูกบอลทอง',note:'ตั้งจิต เลือกจำนวนหลัก แล้วลุ้นเลขทีละลูก',label:'THE GOLDEN ORB',href:'index.html'},sticks:{x:72,y:74,title:'ซุ้มเซียมซีข้อคิด',note:'เขย่ากระบอก แล้วเลือกเก็บข้อคิดที่มีความหมายกับคุณ',label:'A LITTLE WISDOM',href:'siamsi.html'},numbers:{x:50,y:83,title:'ซุ้มเปิดชุดเลข',note:'สำรวจชุดเลขที่ชอบ · เปิดได้ 3 ครั้งต่อวันในเบราว์เซอร์นี้',label:'YOUR NEXT POSSIBILITY',href:'lucky-numbers.html'}};
Object.assign(stations,{cabinet:{x:79,y:57,title:'ตู้รับใบเซียมซี',note:'รับใบตามเลขบนไม้ที่ได้จากการเขย่า',label:'YOUR FORTUNE LEAF'},donation:{x:27,y:57,title:'ตู้บริจาคจำลอง',note:'พื้นที่ตั้งใจทำความดี ไม่มีการรับเงินหรือออกใบอนุโมทนา',label:'A GOOD INTENTION'},info:{x:23,y:83,title:'ข้อปฏิบัติในลาน',note:'ใช้งานอย่างเคารพกัน และไม่เปิดเผยข้อมูลส่วนตัว',label:'WELCOME'}});
let navigateOnArrival=false;
let scene3d=null,sceneLoading=false,preferenceKey=null,intentionKey=null,look=appearance(),waiTimer=null;
let offering={flower:'none',incense:false,candle:false};
const presence=createSanctuaryPresence({onPeers:peers=>{scene3d?.setPeers(peers);$('presence-peers').replaceChildren();for(const p of peers.slice(0,16)){const li=document.createElement('li');li.textContent=p.alias;$('presence-peers').append(li);}},onStatus:(message,active)=>{$('presence-status').textContent=message;$('presence-join').hidden=active;$('presence-leave').hidden=!active;$('presence-alias').disabled=active;$('presence-greet').disabled=!active;$('sanctuary-session').textContent=active?'ลานร่วม':'พื้นที่ส่วนตัว';},onCount:count=>{$('presence-count').textContent=count?'ตัวละครในลาน '+count+' ตัว (รวมคุณ)':'พื้นที่ส่วนตัว';}});
let position={x:50,y:77},target={...position},frame=0,last=0,selected=null,owner=null;
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches||document.documentElement.dataset.effects==='soft';
function paint(){presence.updatePosition(position.x,position.y);scene3d?.setAvatar(position.x,position.y,avatar.classList.contains('is-walking'));avatar.style.left=position.x+'%';avatar.style.top=position.y+'%';avatar.style.zIndex=String(Math.round(position.y));}
function arrive(){presence.updatePosition(position.x,position.y,{force:true});avatar.classList.remove('is-walking');scene3d?.setAvatar(position.x,position.y,false);$('walk-marker').hidden=true;frame=0;last=0;if(selected){const site=stations[selected];$('garden-status').textContent='ถึงแล้ว · '+site.title;showAction(selected);if(navigateOnArrival){navigateOnArrival=false;enterStation(selected);}}else{$('garden-status').textContent='เลือกซุ้มที่อยากไป หรือแตะพื้นเพื่อเดินต่อ';$('garden-enter').hidden=true;$('garden-pray').hidden=true;$('garden-action-title').textContent='วันนี้ อยากให้เวลากับอะไร?';$('garden-action-note').textContent='เลือกซุ้มเพื่อเดินและเปิดหน้ากิจกรรม หรือใช้ปุ่มทางลัดด้านล่าง';$('garden-action-kicker').textContent='WELCOME TO YOUR SANCTUARY';}}
function step(now){if(document.hidden){frame=0;last=0;return;}const dt=last?Math.min((now-last)/1000,.05):0;last=now;const dx=target.x-position.x,dy=target.y-position.y;const rect=world.getBoundingClientRect(),distance=Math.hypot(dx*rect.width/100,dy*rect.height/100),travel=160*dt;
 if(distance<=Math.max(travel,1)){position={...target};paint();arrive();return;}
 position.x+=dx*travel/distance;position.y+=dy*travel/distance;paint();frame=requestAnimationFrame(step);
}
function walk(x,y,key=null){if(!key)navigateOnArrival=false;target={x:Math.max(10,Math.min(90,x)),y:Math.max(53,Math.min(89,y))};selected=key;$('walk-marker').style.left=target.x+'%';$('walk-marker').style.top=target.y+'%';$('walk-marker').hidden=false;
 if(reduced()){if(frame)cancelAnimationFrame(frame);position={...target};paint();arrive();return;}
 avatar.classList.add('is-walking');avatar.style.setProperty('--facing',target.x<position.x?-1:1);$('garden-status').textContent=key?'กำลังเดินไป · '+stations[key].title:'กำลังเดิน…';if(!frame){last=0;frame=requestAnimationFrame(step);}}
function enterStation(key){if(key==='altar'){if(document.body.classList.contains('worship-mode')){$('garden-pray').click();}else location.assign('worship.html');}else if(stations[key].href)location.assign(stations[key].href);else openTemple(key);}
function selectStation(key){if(!stations[key])return;scene3d?.setCloseup(false);world.classList.remove('altar-closeup');navigateOnArrival=true;showAction(key);walk(stations[key].x,stations[key].y,key);}
function showAction(key){const site=stations[key];$('garden-action-title').textContent=site.title;$('garden-action-note').textContent=site.note;$('garden-action-kicker').textContent=site.label;$('garden-enter').hidden=!site.href;$('garden-pray').hidden=key!=='altar';if(['cabinet','donation','info'].includes(key)){$('garden-enter').hidden=false;$('garden-enter').href='#';$('garden-enter').textContent='เปิด'+site.title;}if(site.href){$('garden-enter').href=site.href;$('garden-enter').textContent='เข้า'+(key==='ball'?'หมุนลูกบอล':key==='sticks'?'เสี่ยงเซียมซี':'เปิดชุดเลข')+' ↗';}document.querySelectorAll('[data-station]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.station===key)));}
for(const button of document.querySelectorAll('[data-station]')){button.setAttribute('aria-pressed','false');button.addEventListener('click',()=>{selectStation(button.dataset.station);});}
world.addEventListener('click',event=>{if(event.target.closest('button')||event.target.closest('canvas'))return;const rect=world.getBoundingClientRect();walk((event.clientX-rect.left)/rect.width*100,(event.clientY-rect.top)/rect.height*100);});
world.addEventListener('keydown',event=>{if(event.target!==world)return;const move={ArrowLeft:[-7,0],a:[-7,0],ArrowRight:[7,0],d:[7,0],ArrowUp:[0,-5],w:[0,-5],ArrowDown:[0,5],s:[0,5]}[event.key];if(!move)return;event.preventDefault();walk(target.x+move[0],target.y+move[1]);});
$('garden-home').addEventListener('click',()=>{navigateOnArrival=false;walk(50,77);});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&frame){cancelAnimationFrame(frame);frame=0;last=0;}else if(!document.hidden&&avatar.classList.contains('is-walking'))frame=requestAnimationFrame(step);});
function initializeOwner(id){if(owner===id&&preferenceKey)return;owner=id;preferenceKey='lucky-sanctuary-look-'+owner;intentionKey='lucky-sanctuary-note-'+owner;try{look=appearance(JSON.parse(localStorage.getItem(preferenceKey)||'{}'));$('intention-note-private').value=cleanNote(localStorage.getItem(intentionKey)||'');}catch{}applyAppearance(false);let nickname='คุณ';try{nickname=localStorage.getItem('lucky-member-player-'+owner)?.trim().slice(0,24)||'คุณ';}catch{}$('avatar-name').textContent=nickname;$('presence-alias').value=nickname==='คุณ'?'':nickname;setupJourney();$('garden-status').textContent='ยินดีต้อนรับ · แตะพื้นเพื่อเดิน หรือเลือกซุ้มที่อยากไป';}
document.addEventListener('lucky-member-ready',event=>initializeOwner(event.detail.id));
document.addEventListener('lucky-member-locked',()=>{owner=null;if(frame)cancelAnimationFrame(frame);frame=0;avatar.classList.remove('is-walking');$('garden-prayer').close();$('intention-note-private').value='';look=appearance();presence.leave();});
$('garden-pray').addEventListener('click',async()=>{const button=$('garden-pray');button.disabled=true;try{const user=await requireMember();if(!user)return;performWai();$('garden-prayer').showModal();document.dispatchEvent(new CustomEvent('lucky-sound',{detail:'reveal'}));}finally{button.disabled=false;}});
$('garden-prayer-close').addEventListener('click',()=>$('garden-prayer').close());
$('garden-prayer').addEventListener('click',event=>{if(event.target===$('garden-prayer')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
paint();$('walk-marker').hidden=true;

function fallback3D(message){for(const id of ['view-altar','place-flower','ritual-incense','ritual-candle','avatar-wai','appearance-preview','scene-quality','scene-mood'])$(id).disabled=true;world.classList.remove('is-3d','altar-closeup');avatar.hidden=false;world.querySelector('canvas')?.setAttribute('hidden','');for(const button of world.querySelectorAll('[data-station]')){button.style.removeProperty('left');button.style.removeProperty('top');}$('garden-render-status').textContent=message;}
async function start3D(){
 if(sceneLoading||scene3d)return;sceneLoading=true;$('garden-render-status').textContent='กำลังเตรียมฉาก 3D…';
 try{await import('./vendor/garden3d.js?v=3.21');scene3d=globalThis.LuckyGarden.createSanctuary(world,{onWalk:(x,y)=>walk(x,y),onStation:selectStation,onReady:()=>{$('view-altar').disabled=false;$('garden-render-status').textContent='3D พร้อมแล้ว · แตะพื้นเพื่อเดิน';},onError:()=>fallback3D('เครื่องนี้เปิด 3D ไม่ได้ · ใช้ซุ้มและปุ่มด้านล่างได้ตามปกติ')});if(scene3d){avatar.hidden=true;scene3d.setAvatar(position.x,position.y,false);scene3d.setAppearance(look);scene3d.setMood($('scene-mood').value);scene3d.setOfferings(offering);scene3d.setQuality($('scene-quality').value);scene3d.setAmbient(!reduced());setupJourney();}}catch{ fallback3D('โหลดฉาก 3D ไม่สำเร็จ · ใช้ปุ่มกิจกรรมด้านล่างได้');}
}
document.addEventListener('lucky-member-ready',start3D);
if(!document.querySelector('[data-member-only]')?.hidden)start3D();
for(const id of ['visitor-color','visitor-skin','visitor-hair'])$(id).addEventListener('change',()=>{look=appearance({color:$('visitor-color').value,skin:$('visitor-skin').value,hairStyle:$('visitor-hair').value});applyAppearance(true);});
$('camera-left').addEventListener('click',()=>scene3d?.turn(-.2));
$('camera-right').addEventListener('click',()=>scene3d?.turn(.2));

$('view-altar').addEventListener('click',()=>{if(!scene3d)return;const active=$('view-altar').getAttribute('aria-pressed')!=='true';$('view-altar').setAttribute('aria-pressed',String(active));$('view-altar').textContent=active?'กลับมุมมองลาน':'ชมองค์พระใกล้ ๆ';world.classList.toggle('altar-closeup',active);scene3d.setCloseup(active);if(active)showAction('altar');});

$('garden-home').addEventListener('click',()=>{scene3d?.setCloseup(false);world.classList.remove('altar-closeup');$('view-altar').setAttribute('aria-pressed','false');$('view-altar').textContent='ชมองค์พระใกล้ ๆ';});

function applyAppearance(save=false){$('visitor-color').value=look.color;$('visitor-skin').value=look.skin;$('visitor-hair').value=look.hairStyle;scene3d?.setAppearance(look);presence.updateAppearance(look);if(save){try{if(preferenceKey)localStorage.setItem(preferenceKey,JSON.stringify(look));$('appearance-status').textContent='จำรูปลักษณ์ในเบราว์เซอร์นี้แล้ว';}catch{$('appearance-status').textContent='ใช้รูปลักษณ์ได้ แต่เครื่องนี้บันทึกไม่ได้';}}}
function showPanel(name,focus=false){for(const tab of document.querySelectorAll('[data-panel]')){const selected=tab.dataset.panel===name;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;$('panel-'+tab.dataset.panel).hidden=!selected;if(selected&&focus)tab.focus();}}
const tabs=[...document.querySelectorAll('[data-panel]')];for(const [i,tab]of tabs.entries()){tab.addEventListener('click',()=>showPanel(tab.dataset.panel));tab.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;showPanel(tabs[next].dataset.panel,true);});}
$('place-flower').addEventListener('click',()=>{offering.flower=$('ritual-flower').value;scene3d?.setOfferings(offering);$('offering-status').textContent='วาง'+(offering.flower==='lotus'?'ดอกบัว':'ดาวเรือง')+'หน้าองค์พระแล้ว';});
for(const key of ['incense','candle'])$('ritual-'+key).addEventListener('change',()=>{offering[key]=$('ritual-'+key).checked;scene3d?.setOfferings(offering);$('offering-status').textContent=(key==='incense'?'ธูป':'เทียน')+(offering[key]?'สว่างขึ้นในลานของคุณ':'ถูกเก็บแล้ว');});
$('clear-offerings').addEventListener('click',()=>{offering={flower:'none',incense:false,candle:false};$('ritual-incense').checked=false;$('ritual-candle').checked=false;scene3d?.setOfferings(offering);$('offering-status').textContent='เก็บเครื่องสักการะแล้ว';});
function performWai(greet=false){if(frame){cancelAnimationFrame(frame);frame=0;last=0;target={...position};avatar.classList.remove('is-walking');}scene3d?.setAvatar(position.x,position.y,false);scene3d?.setPose('wai');presence.updatePosition(position.x,position.y,{force:true,pose:'wai'});$('offering-status').textContent=greet?'ส่งความปรารถนาดีให้ผู้ร่วมลานแล้ว':'ประนมมือ ตั้งจิตให้สงบ';clearTimeout(waiTimer);waiTimer=setTimeout(()=>{scene3d?.setPose('idle');presence.updatePosition(position.x,position.y,{force:true,pose:'idle'});},3200);}
$('avatar-wai').addEventListener('click',()=>performWai());$('presence-greet').addEventListener('click',()=>{performWai(true);$('presence-greet').disabled=true;setTimeout(()=>{$('presence-greet').disabled=!presence.active;},5000);});
$('appearance-preview').addEventListener('click',()=>{if(frame)cancelAnimationFrame(frame);frame=0;last=0;target={...position};avatar.classList.remove('is-walking');scene3d?.setAvatar(position.x,position.y,false);scene3d?.setVisitorView(true);world.classList.add('altar-closeup');$('appearance-status').textContent='ใช้ปุ่มลูกศรเหนือฉากเปลี่ยนมุมดูได้ · กดกลับกลางลานเพื่อจบ';});
$('scene-mood').addEventListener('change',()=>scene3d?.setMood($('scene-mood').value));$('scene-quality').addEventListener('change',()=>scene3d?.setQuality($('scene-quality').value));
$('presence-join').addEventListener('click',async()=>{const button=$('presence-join');if(presence.joining)return;button.disabled=true;try{if(!await requireMember())return;await presence.join($('presence-alias').value,look);}catch(error){$('presence-status').textContent=error.message;}finally{button.disabled=false;}});$('presence-leave').addEventListener('click',()=>presence.leave());
$('save-intention').addEventListener('click',()=>{try{if(!intentionKey)throw new Error();localStorage.setItem(intentionKey,cleanNote($('intention-note-private').value));$('intention-status').textContent='เก็บบันทึกไว้ในเบราว์เซอร์นี้แล้ว · ไม่ได้อัปโหลด';}catch{$('intention-status').textContent='เครื่องนี้บันทึกไม่ได้ กรุณาคัดลอกข้อความเก็บไว้เอง';}});
let breathTimer=null,breathStart=0;function stopBreath(message){clearInterval(breathTimer);breathTimer=null;$('breath-start').textContent='เริ่มพักใจ 30 วินาที';$('breath-status').textContent=message;}
$('breath-start').addEventListener('click',()=>{if(breathTimer){stopBreath('พักได้ตามจังหวะของคุณ');return;}breathStart=Date.now();$('breath-progress').value=0;$('breath-start').textContent='จบช่วงพักใจ';$('breath-status').textContent='คลายไหล่ แล้วหายใจตามสบาย';breathTimer=setInterval(()=>{const seconds=Math.min(30,Math.floor((Date.now()-breathStart)/1000));$('breath-progress').value=seconds;$('breath-status').textContent=seconds<10?'คลายไหล่ แล้วหายใจตามสบาย':seconds<20?'ปล่อยความคิดผ่านไป ไม่ต้องรีบ':'กลับมารับรู้สิ่งรอบตัวอย่างเบาใจ';if(seconds===30)stopBreath('ครบช่วงพักใจแล้ว ขอให้คุณก้าวต่ออย่างสงบ');},500);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&breathTimer)stopBreath('พักช่วงหายใจเมื่อออกจากหน้าแล้ว');});
let bell; $('ritual-bell').addEventListener('click',()=>{try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw new Error();bell||=new Audio();bell.resume();const now=bell.currentTime;for(const [i,freq]of [440,880,1320].entries()){const oscillator=bell.createOscillator(),gain=bell.createGain();oscillator.frequency.value=freq;gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.025/(i+1),now+.02);gain.gain.exponentialRampToValueAtTime(.0001,now+2.5);oscillator.connect(gain);gain.connect(bell.destination);oscillator.start(now);oscillator.stop(now+2.6);}$('offering-status').textContent='ระฆังหนึ่งครั้ง เพื่อเริ่มต้นอย่างสงบ';}catch{$('offering-status').textContent='เครื่องนี้ยังเปิดเสียงไม่ได้';}});
let tourIndex=-1;const tour=['altar','ball','sticks','numbers'];function tourStep(){navigateOnArrival=false;const key=tour[tourIndex];$('tour-text').textContent=(tourIndex+1)+' / 4 · '+stations[key].title+' — '+stations[key].note;showAction(key);walk(stations[key].x,stations[key].y,key);$('tour-next').textContent=tourIndex===3?'กลับกลางลาน':'จุดถัดไป';}
$('garden-tour').addEventListener('click',()=>{tourIndex=0;$('tour-panel').hidden=false;$('garden-home').click();tourStep();});$('tour-next').addEventListener('click',()=>{if(tourIndex>=3){$('tour-stop').click();return;}tourIndex++;tourStep();});$('tour-stop').addEventListener('click',()=>{tourIndex=-1;$('tour-panel').hidden=true;$('garden-home').click();});

if(!document.querySelector('[data-member-only]')?.hidden&&!owner)requireMember().then(user=>{if(user&&!owner)initializeOwner(user.id);});

$('setting-soft')?.addEventListener('change',()=>scene3d?.setAmbient(!reduced()));matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>scene3d?.setAmbient(!reduced()));

$('garden-enter').addEventListener('click',event=>{if(selected&&['cabinet','donation','info'].includes(selected)){event.preventDefault();openTemple(selected);}});
$('character-edit').addEventListener('click',async()=>{if(!owner)return;const profile=await ensureCharacter({id:owner},{edit:true});try{look=appearance(JSON.parse(localStorage.getItem(preferenceKey)||'{}'));applyAppearance(false);}catch{}$('avatar-name').textContent=profile.alias;$('presence-alias').value=profile.alias;});
function openTemple(key){const modal=$('temple-dialog');$('temple-title').textContent=stations[key].title;$('temple-message').textContent=stations[key].note;$('temple-feedback').textContent='';$('temple-link').hidden=true;$('cabinet-grid').hidden=key!=='cabinet';$('temple-good-deed').hidden=key!=='donation';
 if(key==='cabinet'){const receipt=pendingLeaf(localStorage,owner);$('cabinet-grid').replaceChildren();for(let row=0;row<7;row++)for(let col=0;col<4;col++){const number=col*7+row+1,b=document.createElement('button');b.textContent=String(number);b.setAttribute('aria-label','ช่องรับใบที่ '+number);b.disabled=receipt?.id!==number;b.setAttribute('aria-current',String(receipt?.id===number));b.addEventListener('click',()=>location.assign('siamsi.html?read='+number));$('cabinet-grid').append(b);}scene3d?.highlightLeaf(receipt?.id);$('temple-message').textContent=receipt?'คุณได้ไม้หมายเลข '+receipt.id+' · เลือกช่องที่สว่างเพื่อรับใบข้อคิด':'ยังไม่มีไม้เซียมซีที่รอรับ · เริ่มเขย่าก่อน แล้วกลับมารับใบที่ตู้นี้';$('temple-link').hidden=false;$('temple-link').href=receipt?'siamsi.html?read='+receipt.id:'siamsi.html';$('temple-link').textContent=receipt?'รับใบที่ '+receipt.id:'ไปเขย่าเซียมซี';}
 if(key==='info')$('temple-message').textContent='เลือกซุ้มเพื่อเดินและเปิดหน้ากิจกรรม · หลังเขย่าเซียมซี กลับมารับใบตามหมายเลขที่ตู้ไม้ · ลานร่วมเป็นทางเลือก ชื่อเล่นไม่ใช่การยืนยันตัวตน · ไม่ต้องโอนเงินหรือให้รหัสผ่านแก่ผู้ร่วมลาน · เนื้อหาเป็นข้อคิดที่แต่งสำหรับเว็บนี้ ไม่ใช่คำทำนายจากวัด';
 modal.showModal();}
$('temple-close').addEventListener('click',()=>$('temple-dialog').close());$('temple-good-deed').addEventListener('click',()=>{$('temple-feedback').textContent='รับความตั้งใจดีของคุณแล้ว ลองช่วยเหลือหรือขอบคุณใครสักคนในวันนี้ · ไม่มีการทำรายการเงิน';});
let journeyOwner=null;function setupJourney(){if(!owner||!scene3d||journeyOwner===owner)return;journeyOwner=owner;const n=requestedLeaf(location.search),receipt=pendingLeaf(localStorage,owner);if(n&&receipt?.id===n){$('journey-notice').hidden=false;$('journey-notice').textContent='ได้ไม้หมายเลข '+n+' · กำลังพาไปตู้รับใบเซียมซี ช่อง '+n;scene3d.highlightLeaf(n);selectStation('cabinet');}else if(document.body.classList.contains('worship-mode')){scene3d.setCloseup(true);world.classList.add('altar-closeup');showAction('altar');}}
